compile.workshop:
settings
{
	main
	{
		Mode Name: "Nested"
	}
	modes
	{
		Deathmatch
		{
			Score To Win: 7
		}
	}
}

variables {
    player:
        0: score
}

rule ("count") {
    event {
        Player Earned Elimination;
        All;
        All;
    }
    actions {
        Modify Player Variable(Event Player, score, Add, 1);
        Modify Player Variable(Event Player, score, Add, 1);
    }
}

